    override val usesAge = false

    private val getFeature: (Element) -> Feature? = ScFeatures::getFeature

    private val nodesFilter by lazy { """
        nodes with
          (leisure = picnic_table or amenity = bbq)
          and access !~ private|no
          and !covered
